690→<!-- Previewing forum posts -->
691→<script>
692→document.addEventListener("DOMContentLoaded", function () {
693→  function escapeHtml(str) {
694→    return str.replace(/[&<>"']/g, m => ({
695→      "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"
696→    })[m]);
697→  }
698→  function normalizeHref(href){
699→    if (!/^https?:\/\/?/i.test(href) && !href.startsWith('/')) {
700→      href = 'https://' + href;
701→    }
702→    return href;
703→  }
704→
705→  function renderPreview(textarea, preview, label) {
706→    let raw = textarea.value;
707→    const anchors = [];
708→    let idx = 0;
709→    raw = raw.replace(/<a\s+href=("(?:[^"]*)"|'(?:[^']*)')\s*>([\s\S]*?)<\/a>/gi,
710→      (match, qHref, labelText) => {
711→        const href = qHref.slice(1, -1);
712→        const token = `__A_TAG_${idx++}__`;
713→        anchors.push({ token, href: normalizeHref(href), label: labelText });
714→        return token;
715→      });
716→    let safe = escapeHtml(raw);
717→    anchors.forEach(a => {
718→      const html = `<a href="${escapeHtml(a.href)}">${escapeHtml(a.label)}</a>`;
719→      safe = safe.replace(a.token, html);
720→    });
721→    safe = safe.replace(/\{PROBLEM=(.+?)\}/g, (_, p1) =>
722→      `<a href="/${escapeHtml(p1)}">[${escapeHtml(p1)}]</a>`
723→    );
724→    safe = safe.replace(/\n/g, "<br>");
725→    if (!safe.trim()) {
726→      preview.classList.add("hidden");
727→      label.classList.add("hidden");
728→      return;
729→    }
730→    preview.innerHTML = safe;
731→    preview.classList.remove("hidden");
732→    label.classList.remove("hidden");
733→    if (window.MathJax && MathJax.Hub) {
734→      MathJax.Hub.Queue(["Typeset", MathJax.Hub, preview]);
735→    }
736→  }
737→  document.querySelectorAll("form textarea").forEach(textarea => {
738→    const form = textarea.closest("form");
739→    const preview = form && form.querySelector(".post-preview");
740→    const label = form && form.querySelector(".preview-label");
741→    if (preview && label) {
742→      textarea.addEventListener("input", () => renderPreview(textarea, preview, label));
743→      renderPreview(textarea, preview, label);
744→    }
745→  });
746→});
747→</script>
