804→<!-- Redirect links and searches when in dual view mode -->
805→<script>
806→document.addEventListener("DOMContentLoaded", function () {
807→  if (!window.location.pathname.startsWith("/dual")) return;
808→
809→  function getTargetPanel() {
810→    const selected = document.querySelector('input[name="targetPanel"]:checked');
811→    return selected ? selected.value : "left";
812→  }
813→
814→  function loadInPanel(panel, path) {
815→    if (!path) return;
816→    const iframe = document.getElementById(`iframe-${panel}`);
817→    if (!iframe) return;
818→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
819→    iframe.src = url;
820→    const inputBox = document.querySelector(`#panel-${panel} input`);
821→    if (inputBox) inputBox.value = path;
822→    console.log(`Loaded "${url}" into panel "${panel}"`);
823→  }
824→  
825→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
826→    link.addEventListener("click", function (e) {
827→      e.preventDefault();
828→      const path = this.getAttribute("href");
829→      loadInPanel(getTargetPanel(), path);
830→    });
831→  });
832→
833→  const idForm = document.getElementById("idsearchForm");
834→  if (idForm) {
835→    idForm.addEventListener("submit", function (e) {
836→      e.preventDefault();
837→      const input = idForm.querySelector(".idsearchTerm").value.trim();
838→      if (!input) return;
839→
840→      let path = null;
841→
842→      if (/^\d+$/.test(input)) {
843→        path = "/go_to/" + encodeURIComponent(input);
844→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
845→        const parts = input.split(/\s+/).filter(Boolean);
846→        path = "/range/" + parts.map(encodeURIComponent).join("/");
847→      } else {
848→        alert("Invalid input format.");
849→        return;
850→      }
851→
852→      loadInPanel(getTargetPanel(), path);
853→    });
854→  }
855→
856→  const searchForm = document.getElementById("searchForm");
857→  if (searchForm) {
858→    searchForm.addEventListener("submit", function (e) {
859→      e.preventDefault();
860→      const input = searchForm.querySelector(".searchTerm").value.trim();
861→      if (!input) return;
862→
863→      const path = "/search/" + encodeURIComponent(input);
864→      loadInPanel(getTargetPanel(), path);
865→    });
866→  }
867→});
868→</script>
